 print(a,'n',len(q),'ic',np.mean(q) if q else np.nan,'icir',np.mean(q)/np.std(q,ddof=1) if len(q)>1 else np.nan)
for h in [5,20]:
 rr=[]
 for i in range(80,len(close)-h):
