import pandas as pd, numpy as np, glob, os
from scipy.stats import spearmanr
files=glob.glob('../persistent/stock_data/*.csv')
assets=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
d={}
for a in assets:
 p='../persistent/stock_data/'+a+'.csv'
 if os.path.exists(p):
  x=pd.read_csv(p); x['date']=pd.to_datetime(x.date); x=x.sort_values('date'); d[a]=x.set_index('date')
# causal overnight gap: negative open vs prior close; forward close return
rows=[]
for a,x in d.items():
 gap=x.open/x.close.shift(1)-1
 fwd=x.close.shift(-5)/x.close-1
 z=pd.DataFrame({'date':x.index,'asset':a,'factor':-gap,'fwd':fwd}).dropna()
 rows.append(z)
r=pd.concat(rows)
ics=[]; nassets=[]
for dt,g in r.groupby('date'):
 g=g.replace([np.inf,-np.inf],np.nan).dropna()
 if len(g)>=8:
  ics.append(spearmanr(g.factor,g.fwd).statistic); nassets.append(len(g))
ics=np.array(ics); valid=r.dropna().groupby('date').size()
print('dates',len(ics),'mean_assets',np.mean(nassets),'coverage',len(r.dropna())/(len(r)+1e-9))
print('IC',ics.mean(),'ICIR',ics.mean()/ics.std(ddof=1),'hit',np.mean(ics>0),'turnover',np.nan)
for lo,hi in [('2020-01-01','2024-12-31'),('2025-01-01','2027-12-31'),('2028-01-01','2030-07-10')]:
 q=r[(r.date>=lo)&(r.date<=hi)]; vals=[]
 for dt,g in q.groupby('date'):
  g=g.dropna()
  if len(g)>=8: vals.append(spearmanr(g.factor,g.fwd).statistic)
 vals=np.array(vals); print(lo,hi,len(vals),vals.mean() if len(vals) else np.nan, vals.mean()/vals.std(ddof=1) if len(vals)>1 else np.nan)
for h in [1,3,5,10,20]:
 rr=[]
 for a,x in d.items():
  gap=-(x.open/x.close.shift(1)-1); fw=x.close.shift(-h)/x.close-1
  rr.append(pd.DataFrame({'date':x.index,'factor':gap,'fwd':fw,'asset':a}))
 q=pd.concat(rr).dropna(); vals=[]
 for dt,g in q.groupby('date'):
  if len(g)>=8: vals.append(spearmanr(g.factor,g.fwd).statistic)
 vals=np.array(vals); print('horizon',h,'IC',vals.mean(),'ICIR',vals.mean()/vals.std(ddof=1),'n',len(vals))
# artifact
r.to_csv('scripts/miner_2_20300711_overnight_gap_reversal_signal.csv',index=False)

