 if d is not None and len(d)>=180: px[s]=d.set_index('date').close.astype(float)
P=pd.DataFrame(px).sort_index(); R=P.pct_change(); net=P.pct_change(40); path=R.abs().rolling(40,min_periods=30).sum(); eff=net/path.replace(0,np.nan); confirm=P.pct_change(10)
